query SessionData {
  sessionData {
    geo_store {
      popup_enabled
      website
      store
      currency
      popup_title
      popup_subline
      popup_button
      popup_copy1
      popup_copy2
      __typename
    }
    customer {
      customer_id
      group_code
      group_id
      language
      gender
      gender_text
      is_new_customer
      email_hash
      landing_url
      auth_method
      uv_user_id
      uv_ref_code
      is_subscribed
      date_of_birth
      lifetime_sales {
        grand_total
        count
        __typename
      }
      rewardpoints
      token
      firstname
      lastname
      email
      default_billing_address {
        postcode
        city
        telephone
        region {
          region_code
          __typename
        }
        country_code
        __typename
      }
      mobile_number
      __typename
    }
    cart {
      ...CartData
      __typename
    }
    __typename
  }
}"}

