{"operationName":"Pdp","variables":{"productId":8814},"query":"query Pdp($productId: String!) {
  products(filter: {product_id: {eq: $productId}}, pageSize: 1) {
    total_count
    items {
      image {
        file
        url
        __typename
      }
      default_media {
        file
        __typename
      }
      product_id
      ... on ConfigurableProduct {
        variants {
          product {
            product_id
            default_media {
              file
              __typename
            }
            media_gallery {
              disabled
              position
              file
              url
              urlThumbnail
              image360
              ... on ProductVideo {
                video_content {
                  video_title
                  video_url
                  __typename
                }
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      media_gallery {
        disabled
        position
        file
        url
        urlThumbnail
        image360
        ... on ProductVideo {
          video_content {
            video_title
            video_url
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    page_info {
      page_size
      current_page
      __typename
    }
    __typename
  }
}"}

